export type MovementPattern = "push" | "pull" | "squat" | "hinge" | "core" | "mobility";

/** A stable, explainable movement taxonomy used by search and future plan rules. */
export const movementPatternForExercise = (exercise: LibraryExercise): MovementPattern => {
  const key = `${exercise.id} ${exercise.en}`.toLowerCase();
  if (/mobility|mobilization|cat-cow|90-90|ankle-rock|wall-slide/.test(key)) return "mobility";
  if (exercise.body === "core" || /pallof|wood chop|dead bug|bird dog|side plank|carry|crunch|plank/.test(key)) return "core";
  if (/press|push|dip|fly|extension|raise/.test(key) && exercise.body !== "back") return "push";
  if (/row|pull|pulldown|chin|curl|shrug|rear delt|face pull/.test(key) || exercise.body === "back") return "pull";
  if (/deadlift|romanian|hinge|bridge|hip thrust|pull-through|good morning/.test(key)) return "hinge";
  return "squat";
};

export const diversifyExerciseIds = (candidateIds: string[], exercises: LibraryExercise[], targetCount: number) => {
  const byPattern = new Map<MovementPattern, string[]>();
  for (const id of candidateIds) {
    const exercise = exercises.find(item => item.id === id);
    if (!exercise) continue;
    const pattern = movementPatternForExercise(exercise);
    const bucket = byPattern.get(pattern) || [];
    bucket.push(id);
    byPattern.set(pattern, bucket);
  }
  const ordered: string[] = [];
  const buckets = [...byPattern.values()];
  while (ordered.length < targetCount && buckets.some(bucket => bucket.length)) {
    for (const bucket of buckets) {
      const next = bucket.shift();
      if (next) ordered.push(next);
      if (ordered.length >= targetCount) break;
    }
  }
  return ordered;
};

